const queries = [
  { query: 'فيلم تركي مدبلج بالعربية كامل 2024',  origin: 'turkish',  language: 'ar_dubbed' },
  { query: 'فيلم هندي مدبلج بالعربية كامل 2024',  origin: 'indian',   language: 'ar_dubbed' },
  { query: 'فيلم كوري مدبلج بالعربية كامل 2024',  origin: 'korean',   language: 'ar_dubbed' },
  { query: 'فيلم أمريكي مدبلج بالعربية كامل 2024',origin: 'american', language: 'ar_dubbed' },
  { query: 'فيلم صيني مدبلج بالعربية كامل',        origin: 'chinese',  language: 'ar_dubbed' },
  { query: 'فيلم مغربي بالدارجة كامل 2024',        origin: 'moroccan', language: 'darija'    },
  { query: 'فيلم مدبلج بالدارجة المغربية كامل',    origin: 'other',    language: 'darija'    },
  { query: 'فيلم رومانسي تركي مدبلج كامل',         origin: 'turkish',  language: 'ar_dubbed' },
  { query: 'فيلم أكشن هندي مدبلج عربي كامل',      origin: 'indian',   language: 'ar_dubbed' },
  { query: 'فيلم كوري رومانسي مدبلج عربي كامل',   origin: 'korean',   language: 'ar_dubbed' }
];
return queries.map(q => ({ json: q }));

const results = $input.first().json.results || [];
const query = $('Generate Queries').item.json;
const enriched = results
  .filter(r => r.embeddable !== false)
  .filter(r => !r.duration_sec || r.duration_sec > 3600)
  .map(r => ({
    ...r,
    origin:   (r.origin   && r.origin   !== 'other') ? r.origin   : query.origin,
    language: (r.language && r.language !== 'ar_dubbed') ? r.language : query.language,
    query: query.query
  }));
console.log(`[Films] ${query.query} → ${results.length} found, ${enriched.length} valid`);
return [{ json: { items: enriched, query: query.query } }];

const items = $input.all();
let imported=0, skipped=0, errors=0;
for (const item of items) {
  imported += item.json.imported || 0;
  skipped  += item.json.skipped  || 0;
  errors   += item.json.errors   || 0;
}
console.log(`[Films] DONE: ${imported} imported, ${skipped} skipped, ${errors} errors`);
return [{ json: { done:true, imported, skipped, errors, run_at: new Date().toISOString() } }];
